package com.spaceagent.platform.runtime.domain;
import java.time.Instant;import java.util.Objects;
/** Immutable per-run Supervisor policy; Organization rollout persistence follows in later units. */
public record SupervisorPolicy(SupervisorPolicyMode mode,boolean killSwitch,boolean providerCandidateAllowed,String policyHash,Instant pinnedAt){public SupervisorPolicy{mode=Objects.requireNonNull(mode);if(policyHash==null||!policyHash.matches("sha256:[0-9a-f]{64}"))throw new IllegalArgumentException("policyHash");Objects.requireNonNull(pinnedAt);if(killSwitch&&mode!=SupervisorPolicyMode.DETERMINISTIC)throw new IllegalArgumentException("kill switch requires deterministic mode");if(mode==SupervisorPolicyMode.DETERMINISTIC&&!providerCandidateAllowed){}if(mode==SupervisorPolicyMode.SHADOW&&providerCandidateAllowed)throw new IllegalArgumentException("shadow cannot execute provider candidate");}public boolean executesProvider(){return !killSwitch&&(mode==SupervisorPolicyMode.OPT_IN||mode==SupervisorPolicyMode.SELECTED_DEFAULT)&&providerCandidateAllowed;}public boolean recordsShadowComparison(){return mode==SupervisorPolicyMode.SHADOW;}}
